#!/bin/bash
set -e

echo "=========================================="
echo "  Instalador Uptime Kuma - 7 SEC MEDIA    "
echo "=========================================="

if [ "$EUID" -ne 0 ]; then
  echo "Por favor ejecuta este script con sudo o como root:"
  echo "sudo bash setup-vps.sh"
  exit 1
fi

if ! command -v docker &> /dev/null; then
    echo "[+] Instalando Docker y Docker Compose..."
    curl -fsSL https://get.docker.com | sh
    systemctl enable --now docker
else
    echo "[✓] Docker ya esta instalado."
fi

APP_DIR="/opt/uptime-kuma-7sec"
mkdir -p "$APP_DIR/uptime-kuma-data"
cd "$APP_DIR"

echo "[+] Guardando logotipo de 7 SEC MEDIA..."
cat << "EOF_LOGO" | base64 -d > "$APP_DIR/logo.png"

EOF_LOGO

echo "[+] Configurando docker-compose.yml..."
cat << "EOF_COMPOSE" > "$APP_DIR/docker-compose.yml"
version: "3.8"

services:
  uptime-kuma:
    image: louislam/uptime-kuma:1
    container_name: uptime-kuma
    restart: always
    volumes:
      - ./uptime-kuma-data:/app/data
      - ./logo.png:/app/dist/icon.png:ro
      - ./logo.png:/app/dist/icon-192.png:ro
      - ./logo.png:/app/dist/icon-512.png:ro
      - ./logo.png:/app/dist/apple-touch-icon.png:ro
    ports:
      - "3001:3001"
    environment:
      - UPTIME_KUMA_PORT=3001
EOF_COMPOSE

echo "[+] Iniciando Uptime Kuma..."
docker compose down 2>/dev/null || true
docker compose up -d

IP=$(curl -s -4 ifconfig.me || curl -s -4 icanhazip.com || echo "TU_IP_VPS")

echo ""
echo "=========================================================="
echo " Instalacion Completada con Exito!"
echo "=========================================================="
echo " Accede a tu panel en:"
echo " http://$IP:3001"
echo ""
echo " La marca 7 SEC MEDIA ya esta integrada en el panel."
echo " Archivos instalados en: $APP_DIR"
echo "=========================================================="
